const raw = $json.output;

const match = raw.match(/\{[\s\S]*\}/);

const ai = JSON.parse(match[0]);

const data = $json;

const fmt = (v) =>
  Number(v || 0).toLocaleString('pt-BR');

const delta = (d) =>
  d >= 0
    ? `▲ ${d}%`
    : `▼ ${Math.abs(d)}%`;

const deltaColor = (d) =>
  d >= 0
    ? '#22C55E'
    : '#EF4444';

const formatNames = {
  shorts: 'Shorts',
  liveStream: 'Lives',
  videoOnDemand: 'Vídeos',
  creatorContentTypeUnspecified: 'Outros'
};

const html = `
<!DOCTYPE html>
<html lang="pt-br">

<head>

<meta charset="UTF-8"/>

<meta
name="viewport"
content="width=device-width, initial-scale=1.0"
/>

<link
href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap"
rel="stylesheet"
/>

<style>

*{
margin:0;
padding:0;
box-sizing:border-box;
}

:root{

--bg:#F8F9FB;
--card:#FFFFFF;
--border:#ECECEC;

--text:#111827;
--muted:#6B7280;

--primary:#FF3366;

--success:#22C55E;
--danger:#EF4444;

}

html,
body{

width:100%;
height:100%;

overflow:hidden;

background:var(--bg);

}

body{

font-family:'Inter',sans-serif;

color:var(--text);

}

#root{

width:1920px;
height:1080px;

overflow:hidden;

background:var(--bg);

transform-origin:top left;

display:flex;
flex-direction:column;

padding:20px 24px;

gap:12px;

}

/* HEADER */

.header{

display:flex;
justify-content:space-between;
align-items:center;

flex-shrink:0;

}

.logo{

font-size:26px;
font-weight:800;

letter-spacing:-1px;

}

.logo span{
color:var(--primary);
}

.period{

background:#fff;

border:1px solid var(--border);

border-radius:999px;

padding:8px 16px;

font-size:13px;
font-weight:600;

color:var(--muted);

}

/* CARD */

.card{

background:#fff;

border:1px solid var(--border);

border-radius:20px;

box-shadow:
0 1px 3px rgba(16,24,40,.06);

}

/* HERO */

.hero{

display:grid;

grid-template-columns:
repeat(6,1fr);

gap:12px;

flex-shrink:0;

}

.kpi{

padding:14px 16px;

display:flex;
flex-direction:column;

gap:6px;

}

.kpi-top{

display:flex;
align-items:center;

gap:10px;

}

.kpi-icon{

width:40px;
height:40px;

border-radius:12px;

display:flex;
align-items:center;
justify-content:center;

flex-shrink:0;

}

.kpi-icon svg{

width:20px;
height:20px;

stroke-width:2.2;

stroke:var(--text);

fill:none;

}

.kpi-title{

font-size:12px;
font-weight:600;

color:var(--muted);

}

.kpi-value{

font-size:38px;
font-weight:800;

letter-spacing:-1.5px;

line-height:1;

}

.kpi-delta{

font-size:16px;
font-weight:700;

margin-top:auto;

}

.queda{

padding:14px 16px;

display:flex;
flex-direction:column;
justify-content:center;

gap:6px;

}

.queda-title{

font-size:18px;
font-weight:800;

display:flex;
align-items:center;

gap:8px;

}

.queda-title svg{

width:18px;
height:18px;

stroke:var(--danger);

fill:none;

stroke-width:2.2;

}

.queda-item{

display:flex;
justify-content:space-between;

font-size:14px;

}

/* SECTION */

.section-card{

padding:14px 16px;

flex-shrink:0;

}

.section-title{

font-size:22px;
font-weight:800;

letter-spacing:-0.5px;

margin-bottom:10px;

}

/* FORMATOS */

.format-grid{

display:grid;

grid-template-columns:
repeat(4,1fr);

gap:12px;

}

.format-card{

padding:14px 16px;

}

.format-top{

display:flex;
align-items:center;

gap:10px;

margin-bottom:10px;

}

.format-icon{

width:38px;
height:38px;

border-radius:12px;

background:#F4F4F5;

display:flex;
align-items:center;
justify-content:center;

flex-shrink:0;

}

.format-icon svg{

width:20px;
height:20px;

stroke:var(--primary);

fill:none;

stroke-width:2.2;

}

.format-name{

font-size:20px;
font-weight:800;

letter-spacing:-0.5px;

}

.format-metrics{

display:grid;

grid-template-columns:1fr 1fr;

gap:8px;

}

.metric-label{

font-size:12px;

color:var(--muted);

margin-bottom:2px;

}

.metric-value{

font-size:16px;
font-weight:700;

}

.metric-footer{

margin-top:10px;

display:flex;

gap:14px;

font-size:13px;

}

/* VIDEOS */

.video-grid{

display:grid;

grid-template-columns:
repeat(5,1fr);

gap:12px;

}

.video{

background:#fff;

border:1px solid var(--border);

border-radius:16px;

overflow:hidden;

position:relative;

box-shadow:
0 1px 3px rgba(16,24,40,.06);

transition:.2s ease;

}

.video:hover{

transform:translateY(-2px);

box-shadow:
0 8px 20px rgba(0,0,0,.06);

}

.video img{

width:100%;
height:150px;

object-fit:cover;

display:block;

}

.rank{

position:absolute;

top:10px;
left:10px;

background:var(--text);

color:#fff;

width:32px;
height:32px;

border-radius:10px;

display:flex;
align-items:center;
justify-content:center;

font-weight:800;
font-size:15px;

border:2px solid rgba(255,255,255,.2);

}

.video-body{

padding:10px 12px;

}

.video-title{

font-size:16px;
font-weight:700;

line-height:1.2;

margin-bottom:6px;

display:-webkit-box;

-webkit-line-clamp:2;
-webkit-box-orient:vertical;

overflow:hidden;

min-height:38px;

letter-spacing:-0.3px;

}

.video-views{

display:flex;
align-items:baseline;

gap:5px;

margin-bottom:8px;

}

.views-big{

font-size:30px;
font-weight:800;

letter-spacing:-1px;

color:var(--primary);

}

.views-label{

font-size:13px;

color:var(--muted);

}

.video-metrics{

display:flex;

gap:16px;

margin-bottom:8px;

}

.video-metric-label{

font-size:11px;

color:var(--muted);

margin-bottom:2px;

}

.video-metric-value{

font-size:14px;
font-weight:700;

}

.bar{

width:100%;
height:4px;

background:var(--border);

border-radius:999px;

overflow:hidden;

}

.bar-fill{

height:100%;

background:var(--primary);

border-radius:999px;

}

/* FOOTER */

.footer{

display:grid;

grid-template-columns:1fr 1fr;

gap:12px;

flex-shrink:0;

}

.footer-box{

padding:14px 16px;

}

.footer-title{

font-size:17px;
font-weight:800;

margin-bottom:8px;

}

.footer-text{

font-size:14px;

line-height:1.5;

color:#374151;

}

ul{
padding-left:16px;
}

li{

margin-bottom:5px;

font-size:14px;

line-height:1.4;

color:#374151;

}

</style>

</head>

<body>

<div id="root">

<!-- HEADER -->

<div class="header">

<div class="logo">
TVCASA <span>Analytics</span>
</div>

<div class="period">
${data.periodo.inicio} → ${data.periodo.fim}
</div>

</div>

<!-- HERO -->

<div class="hero">

${Object.entries(data.grandes_numeros).map(([k,v]) => {

const icons = {

views: `
<svg viewBox="0 0 24 24">
<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7Z"/>
<circle cx="12" cy="12" r="3"/>
</svg>
`,

likes: `
<svg viewBox="0 0 24 24">
<path d="M12 21s-6.7-4.35-9.33-8A5.33 5.33 0 0 1 12 6a5.33 5.33 0 0 1 9.33 7c-2.63 3.65-9.33 8-9.33 8Z"/>
</svg>
`,

comentarios: `
<svg viewBox="0 0 24 24">
<path d="M21 15a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4Z"/>
</svg>
`,

inscritos: `
<svg viewBox="0 0 24 24">
<path d="M20 21a8 8 0 1 0-16 0"/>
<circle cx="12" cy="7" r="4"/>
</svg>
`,

tempo_assistido: `
<svg viewBox="0 0 24 24">
<circle cx="12" cy="12" r="9"/>
<path d="M12 7v5l3 3"/>
</svg>
`
};

const colors = {
views:'#EEF4FF',
likes:'#FFF1F2',
comentarios:'#ECFDF3',
inscritos:'#F5F3FF',
tempo_assistido:'#FFF7ED'
};

return `

<div class="card kpi">

<div class="kpi-top">

<div
class="kpi-icon"
style="background:${colors[k]}"
>

${icons[k]}

</div>

<div class="kpi-title">
${k.replace('_',' ').toUpperCase()}
</div>

</div>

<div class="kpi-value">
${fmt(v.valor)}
</div>

<div
class="kpi-delta"
style="color:${deltaColor(v.delta)}"
>
${delta(v.delta)}
</div>

</div>

`;

}).join('')}

<div class="card queda">

<div class="queda-title">

<svg viewBox="0 0 24 24">
<path d="M3 3v18h18"/>
<path d="m19 9-5 5-4-4-5 5"/>
</svg>

<span>Queda</span>

</div>

<div class="queda-item">

<span>Views</span>

<span style="
color:#EF4444;
font-weight:700;
">

${delta(data.grandes_numeros.views.delta)}

</span>

</div>

<div class="queda-item">

<span>Likes</span>

<span style="
color:#EF4444;
font-weight:700;
">

${delta(data.grandes_numeros.likes.delta)}

</span>

</div>

</div>

</div>

<!-- FORMATOS -->

<div class="card section-card">

<div class="section-title">
Formatos
</div>

<div class="format-grid">

${data.formatos.map(f => {

const icons = {

Shorts: `
<svg viewBox="0 0 24 24">
<path d="M8 7c0-2 8-2 8-4 0-1.5-2-3-4-3S8 1.5 8 3"/>
<path d="M16 17c0 2-8 2-8 4 0 1.5 2 3 4 3s4-1.5 4-3"/>
<path d="M8 7c0 2 8 2 8 4s-8 2-8 4"/>
</svg>
`,

Lives: `
<svg viewBox="0 0 24 24">
<circle cx="12" cy="12" r="2"/>
<path d="M16.24 7.76a6 6 0 0 1 0 8.48"/>
<path d="M7.76 16.24a6 6 0 0 1 0-8.48"/>
<path d="M19.07 4.93a10 10 0 0 1 0 14.14"/>
<path d="M4.93 19.07a10 10 0 0 1 0-14.14"/>
</svg>
`,

Vídeos: `
<svg viewBox="0 0 24 24">
<path d="M8 5v14l11-7Z"/>
</svg>
`,

Outros: `
<svg viewBox="0 0 24 24">
<circle cx="5" cy="12" r="1.5"/>
<circle cx="12" cy="12" r="1.5"/>
<circle cx="19" cy="12" r="1.5"/>
</svg>
`
};

const alias =
formatNames[f.tipo] || f.tipo;

return `

<div class="card format-card">

<div class="format-top">

<div class="format-icon">
${icons[alias]}
</div>

<div class="format-name">
${alias}
</div>

</div>

<div class="format-metrics">

<div>

<div class="metric-label">
Views
</div>

<div class="metric-value">
${fmt(f.views)}
</div>

</div>

<div>

<div class="metric-label">
Retenção
</div>

<div class="metric-value">
${f.retencao}%
</div>

</div>

</div>

<div class="metric-footer">

<div>
Inscritos:
<b>${f.inscritos}</b>
</div>

<div>
Eficiência:
<b>${f.eficiencia}</b>
</div>

</div>

</div>

`;

}).join('')}

</div>

</div>

<!-- TOP VIDEOS -->

<div
class="card section-card"
style="
flex:1;
min-height:0;
"
>

<div class="section-title">
Top Conteúdos
</div>

<div class="video-grid">

${data.top_videos.map((v,index) => `

<div class="video">

<div class="rank">
${index + 1}
</div>

<img
src="${v.thumb}"
loading="lazy"
/>

<div class="video-body">

<div class="video-title">
${v.titulo}
</div>

<div class="video-views">

<div class="views-big">
${fmt(v.views)}
</div>

<div class="views-label">
views
</div>

</div>

<div class="video-metrics">

<div>

<div class="video-metric-label">
retenção
</div>

<div class="video-metric-value">
${v.retencao}%
</div>

</div>

<div>

<div class="video-metric-label">
engajamento
</div>

<div class="video-metric-value">
${v.engajamento}%
</div>

</div>

</div>

<div class="bar">

<div
class="bar-fill"
style="
width:${Math.min(v.retencao,100)}%
"
></div>

</div>

</div>

</div>

`).join('')}

</div>

</div>

<!-- FOOTER -->

<div class="footer">

<div class="card footer-box">

<div class="footer-title">
Diagnóstico
</div>

<div class="footer-text">
${ai.diagnostico_formato}
</div>

</div>

<div class="card footer-box">

<div class="footer-title">
Próximas ações
</div>

<ul>

${ai.acoes_proxima_semana
.map(a => `<li>${a}</li>`)
.join('')}

</ul>

</div>

</div>

</div>

<script>

(function(){

const root =
document.getElementById('root');

function scale(){

const scaleX =
window.innerWidth / 1920;

const scaleY =
window.innerHeight / 1080;

const factor =
Math.min(scaleX,scaleY);

root.style.transform =
'scale(' + factor + ')';

document.body.style.width =
Math.round(1920 * factor) + 'px';

document.body.style.height =
Math.round(1080 * factor) + 'px';

}

window.addEventListener(
'resize',
scale
);

scale();

})();

</script>

</body>
</html>
`;

const buffer =
Buffer.from(html, 'utf8');

return {

json: {
fileName: 'report.html',
},

binary: {

data:
await this.helpers.prepareBinaryData(
buffer,
'report.html',
'text/html'
),

},

};

const items = $input.all();

const formatoAtual = items[0].json;
const formatoAnterior = items[1].json;
const videosAtual = items[2].json;
const videosAnterior = items[3].json;

function mapRows(data) {

  const headers = data.columnHeaders.map(h => h.name);

  return data.rows.map(row => {

    const obj = {};

    headers.forEach((h, i) => {
      obj[h] = row[i];
    });

    return obj;
  });
}

const formatosAtual = mapRows(formatoAtual);
const formatosAnterior = mapRows(formatoAnterior);

const videosA = mapRows(videosAtual);
const videosB = mapRows(videosAnterior);

function calcDelta(a, b) {

  if (!b || b === 0) return 0;

  return Number((((a - b) / b) * 100).toFixed(1));
}

function sumMetric(rows, key) {

  return rows.reduce((acc, r) => {

    return acc + Number(r[key] || 0);

  }, 0);
}

const totalAtual = {
  views: sumMetric(videosA, 'views'),
  likes: sumMetric(videosA, 'likes'),
  comments: sumMetric(videosA, 'comments'),
  inscritos: sumMetric(videosA, 'subscribersGained'),
  watch: sumMetric(videosA, 'estimatedMinutesWatched'),
};

const totalAnterior = {
  views: sumMetric(videosB, 'views'),
  likes: sumMetric(videosB, 'likes'),
  comments: sumMetric(videosB, 'comments'),
  inscritos: sumMetric(videosB, 'subscribersGained'),
  watch: sumMetric(videosB, 'estimatedMinutesWatched'),
};

const grandes_numeros = {

  views: {
    valor: totalAtual.views,
    delta: calcDelta(totalAtual.views, totalAnterior.views)
  },

  likes: {
    valor: totalAtual.likes,
    delta: calcDelta(totalAtual.likes, totalAnterior.likes)
  },

  comentarios: {
    valor: totalAtual.comments,
    delta: calcDelta(totalAtual.comments, totalAnterior.comments)
  },

  inscritos: {
    valor: totalAtual.inscritos,
    delta: calcDelta(totalAtual.inscritos, totalAnterior.inscritos)
  },

  tempo_assistido: {
    valor: (totalAtual.watch / 60).toFixed(1),
    delta: calcDelta(totalAtual.watch, totalAnterior.watch)
  }
};

const formatos = formatosAtual.map(f => {

  const eficiencia =
    (
      (f.averageViewPercentage * 1.5) +
      (f.subscribersGained * 10) +
      ((f.likes / Math.max(f.views,1)) * 100)
    ).toFixed(0);

  return {

    tipo: f.creatorContentType,

    views: f.views,

    likes: f.likes,

    comentarios: f.comments,

    inscritos: f.subscribersGained,

    retencao: Number(f.averageViewPercentage).toFixed(1),

    watchTime: (f.estimatedMinutesWatched / 60).toFixed(1),

    eficiencia
  };
});

const top_videos = videosA
  .map(v => {

    const score =
      Math.round(
        (v.views * 0.3) +
        (v.likes * 2) +
        (v.comments * 4) +
        (v.subscribersGained * 8) +
        (v.averageViewPercentage * 1.5)
      );

    return {

      id: v.video,

      thumb: `https://i.ytimg.com/vi/${v.video}/mqdefault.jpg`,

      titulo: v.title || v.video,

      views: v.views,

      likes: v.likes,

      comentarios: v.comments,

      inscritos: v.subscribersGained,

      retencao: Number(v.averageViewPercentage).toFixed(1),

      watchTime: (v.estimatedMinutesWatched / 60).toFixed(1),

      engajamento:
        (
          ((v.likes + v.comments) / Math.max(v.views,1)) * 100
        ).toFixed(1),

      score
    };
  })
  .sort((a,b) => b.score - a.score)
  .slice(0,5);

return [
  {
    json: {

      periodo: {

        inicio:
          $today.minus(7, 'days').toFormat('dd/MM'),

        fim:
          $today.toFormat('dd/MM')
      },

      grandes_numeros,

      formatos,

      top_videos
    }
  }
];

const analytics = $('Analytics Vídeo Atual').first().json;
const youtube = $json;

const titleMap = {};

youtube.items.forEach(v => {
  titleMap[v.id] = v.snippet.title;
});

analytics.rows = analytics.rows.map(r => {
  r.push(titleMap[r[0]] || r[0]);
  return r;
});

analytics.columnHeaders.push({
  name: 'title',
  columnType: 'DIMENSION',
  dataType: 'STRING'
});

return [
  {
    json: analytics
  }
];

const myBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = myBuffer.toString('base64');
return [
  { json: { number: '5561985254499', image: base64, caption: 'Relatório Semanal YouTube' } },
  { json: { number: '5561985839517', image: base64, caption: 'Relatório Semanal YouTube' } }
];
